using System.Reflection;
using System.Reflection.Metadata;
using System.Reflection.PortableExecutable;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.ArchitectureTest;

// Reads compiled metadata, so it also sees types pulled in via implicit usings or fully qualified names.
public class LayerDependencyTests
{
    private static readonly string[] TechnicalNamespaces =
    [
        "System.IO", "System.Net", "System.Data", "System.Diagnostics.Process",
        "Microsoft.Data", "Microsoft.EntityFrameworkCore", "Microsoft.Extensions.Http",
    ];

    private const string Domain = "PaymentAuthorization.Domain";
    private const string Application = "PaymentAuthorization.Application";
    private const string Infrastructure = "PaymentAuthorization.Infrastructure";

    [Fact]
    public void Domain_depends_on_no_other_layer_and_no_technical_detail() =>
        AssertNoViolations(typeof(Money).Assembly, [Application, Infrastructure]);

    [Fact]
    public void Application_depends_on_no_infrastructure_and_no_technical_detail() =>
        AssertNoViolations(typeof(AuthorizePayment).Assembly, [Infrastructure]);

    [Fact]
    public void Infrastructure_does_not_reach_around_Application_into_nothing_else_it_should_not() =>
        Assert.Contains(Application, ReferencedAssemblyNames(typeof(HttpPaymentGateway).Assembly));

    private static void AssertNoViolations(Assembly assembly, string[] forbiddenAssemblies)
    {
        var references = ReferencedAssemblyNames(assembly);
        var violations = forbiddenAssemblies.Where(references.Contains)
            .Select(a => $"references assembly {a}")
            .Concat(ReferencedTypes(assembly)
                .Where(t => TechnicalNamespaces.Any(n => t == n || t.StartsWith(n + ".")))
                .Distinct().Select(t => $"uses technical type namespace {t}"))
            .ToList();

        Assert.True(violations.Count == 0,
            $"{assembly.GetName().Name} breaks layering:{Environment.NewLine}{string.Join(Environment.NewLine, violations)}");
    }

    private static HashSet<string> ReferencedAssemblyNames(Assembly assembly) =>
        assembly.GetReferencedAssemblies().Select(a => a.Name!).ToHashSet();

    private static IEnumerable<string> ReferencedTypes(Assembly assembly)
    {
        using var pe = new PEReader(File.OpenRead(assembly.Location));
        var md = pe.GetMetadataReader();
        return md.TypeReferences
            .Select(h => md.GetTypeReference(h))
            .Select(t => $"{md.GetString(t.Namespace)}.{md.GetString(t.Name)}")
            .ToList();
    }
}
